#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <sys/stat.h>
#include <errno.h>
#include <ctype.h>

#define MAX_FILENAME 256
#define MAX_CONTENT_TYPE 128
#define UPLOAD_DIR "/var/uploads/"
#define RATE_LIMIT_WINDOW 60
#define RATE_LIMIT_MAX 10
#define MAX_RETRIES 3
#define MAX_FILE_SIZE (10 * 1024 * 1024)

typedef struct {
    time_t timestamps[RATE_LIMIT_MAX];
    int count;
    char client_ip[46];
} rate_limit_entry_t;

typedef struct {
    char filename[MAX_FILENAME];
    char content_type[MAX_CONTENT_TYPE];
    unsigned char *data;
    size_t data_len;
    char client_ip[46];
} upload_request_t;

static rate_limit_entry_t rate_table[1024];
static int rate_table_size = 0;

static const char *ALLOWED_EXTENSIONS[] = {".jpg", ".jpeg", ".png", ".gif", ".pdf", NULL};
static const char *ALLOWED_CONTENT_TYPES[] = {"image/jpeg", "image/png", "image/gif", "application/pdf", NULL};

int check_rate_limit(const char *client_ip) {
    time_t now = time(NULL);
    rate_limit_entry_t *entry = NULL;

    for (int i = 0; i < rate_table_size; i++) {
        if (strcmp(rate_table[i].client_ip, client_ip) == 0) {
            entry = &rate_table[i];
            break;
        }
    }

    if (!entry) {
        if (rate_table_size >= 1024) return -1;
        entry = &rate_table[rate_table_size++];
        strncpy(entry->client_ip, client_ip, 45);
        entry->client_ip[45] = '\0';
        entry->count = 0;
    }

    int valid = 0;
    for (int i = 0; i < entry->count; i++) {
        if (now - entry->timestamps[i] < RATE_LIMIT_WINDOW) {
            entry->timestamps[valid++] = entry->timestamps[i];
        }
    }
    entry->count = valid;

    if (entry->count >= RATE_LIMIT_MAX) return -1;

    entry->timestamps[entry->count++] = now;
    return 0;
}

int validate_content_type(const char *content_type) {
    for (int i = 0; ALLOWED_CONTENT_TYPES[i] != NULL; i++) {
        if (strcasecmp(content_type, ALLOWED_CONTENT_TYPES[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

int validate_extension(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (!dot) return 0;

    for (int i = 0; ALLOWED_EXTENSIONS[i] != NULL; i++) {
        if (strcasecmp(dot, ALLOWED_EXTENSIONS[i]) == 0) {
            return 1;
        }
    }
    return 0;
}

int sanitize_filename(const char *input, char *output, size_t outlen) {
    if (!input || !output || outlen == 0) return -1;

    const char *base = strrchr(input, '/');
    if (base) base++; else base = input;

    const char *winbase = strrchr(base, '\\');
    if (winbase) base = winbase + 1;

    size_t j = 0;
    for (size_t i = 0; base[i] && j < outlen - 1; i++) {
        if (isalnum((unsigned char)base[i]) || base[i] == '.' || base[i] == '-' || base[i] == '_') {
            output[j++] = base[i];
        }
    }
    output[j] = '\0';

    if (j == 0) return -1;
    if (strstr(output, "..")) return -1;

    return 0;
}

int validate_magic_bytes(const unsigned char *data, size_t len, const char *content_type) {
    if (len < 8) return 0;

    if (strcasecmp(content_type, "image/jpeg") == 0) {
        return (data[0] == 0xFF && data[1] == 0xD8 && data[2] == 0xFF);
    } else if (strcasecmp(content_type, "image/png") == 0) {
        return (data[0] == 0x89 && data[1] == 0x50 && data[2] == 0x4E && data[3] == 0x47);
    } else if (strcasecmp(content_type, "image/gif") == 0) {
        return (data[0] == 'G' && data[1] == 'I' && data[2] == 'F' && data[3] == '8');
    } else if (strcasecmp(content_type, "application/pdf") == 0) {
        return (data[0] == '%' && data[1] == 'P' && data[2] == 'D' && data[3] == 'F');
    }
    return 0;
}

int write_file_with_retry(const char *path, const unsigned char *data, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        FILE *fp = fopen(path, "wb");
        if (!fp) {
            retries++;
            usleep(100000 * (1 << retries));
            continue;
        }

        size_t written = fwrite(data, 1, len, fp);
        fclose(fp);

        if (written == len) {
            chmod(path, 0644);
            return 0;
        }

        unlink(path);
        retries++;
        usleep(100000 * (1 << retries));
    }
    return -1;
}

int handle_upload(upload_request_t *req) {
    if (!req) return -1;

    if (check_rate_limit(req->client_ip) != 0) {
        return -2;
    }

    if (req->data_len == 0 || req->data_len > MAX_FILE_SIZE) {
        return -3;
    }

    if (!validate_content_type(req->content_type)) {
        return -4;
    }

    char safe_name[MAX_FILENAME];
    if (sanitize_filename(req->filename, safe_name, sizeof(safe_name)) != 0) {
        return -5;
    }

    if (!validate_extension(safe_name)) {
        return -6;
    }

    if (!validate_magic_bytes(req->data, req->data_len, req->content_type)) {
        return -7;
    }

    char final_path[512];
    snprintf(final_path, sizeof(final_path), "%s%s", UPLOAD_DIR, safe_name);

    /* Cross-reference extension against content_type for consistency */
    const char *ext = strrchr(safe_name, '.');
    if (ext) {
        int consistent = 0;
        if ((strcasecmp(ext, ".jpg") == 0 || strcasecmp(ext, ".jpeg") == 0) &&
            strcasecmp(req->content_type, "image/jpeg") == 0) consistent = 1;
        if (strcasecmp(ext, ".png") == 0 &&
            strcasecmp(req->content_type, "image/png") == 0) consistent = 1;
        if (strcasecmp(ext, ".gif") == 0 &&
            strcasecmp(req->content_type, "image/gif") == 0) consistent = 1;
        if (strcasecmp(ext, ".pdf") == 0 &&
            strcasecmp(req->content_type, "application/pdf") == 0) consistent = 1;
        /* Log inconsistency but allow upload for backward compatibility */
        if (!consistent) {
            fprintf(stderr, "WARN: extension/content-type mismatch for %s\n", safe_name);
        }
    }

    return write_file_with_retry(final_path, req->data, req->data_len);
}

int main(int argc, char *argv[]) {
    printf("Upload microservice ready\n");

    /* Example: simulated upload */
    upload_request_t req;
    memset(&req, 0, sizeof(req));
    strncpy(req.filename, "test.jpg", MAX_FILENAME - 1);
    strncpy(req.content_type, "image/jpeg", MAX_CONTENT_TYPE - 1);
    strncpy(req.client_ip, "192.168.1.1", 45);

    unsigned char fake_jpg[] = {0xFF, 0xD8, 0xFF, 0xE0, 0x00, 0x10, 0x4A, 0x46, 0x49, 0x46};
    req.data = fake_jpg;
    req.data_len = sizeof(fake_jpg);

    int result = handle_upload(&req);
    printf("Upload result: %d\n", result);

    return 0;
}
